SET NOCOUNT ON

DROP TABLE IF EXISTS #DiffData

CREATE TABLE #DiffData (
	  CustId INT
	, recommend INT
	, DiffAmt MONEY
	, DateAffect SMALLDATETIME -- Date of detection diff data
	, Isfinished BIT  DEFAULT(0)
)


	----------lệch bên DB06
	(32043840, -0.0197, '2022-01-01 00:00:00'),
	(101647305, -16.00, '2023-11-20 00:00:00'),
	(75784842, -10.00, '2023-01-11 00:00:00'),
	(69431099, -5.00, '2023-01-11 00:00:00'),
	(75579306, -5.00, '2023-01-11 00:00:00')

UPDATE a
SET a.recommend = b.recommend
FROM #DiffData a
	INNER JOIN bodb02..custInfo b (NOLOCK) ON a.custid = b.custid

DROP TABLE IF EXISTS rptDepWinlost_bk_20240425
DROP TABLE IF EXISTS rptDepWinlost_Main_20240425

SELECT b.winlostdate, b.custid, b.currency ,b.OpeningBalance ,b.Deposit ,b.Withdrawal ,b.Turnover ,b.Winloss ,b.ClosingBalance
INTO rptDepWinlost_bk_20240425
FROM #DiffData a
    INNER JOIN dbo.rptDepWinlost_bk b WITH (NOLOCK) ON a.recommend = b.recommend  AND a.CustId = b.custid AND b.winlostdate >= a.DateAffect
    
SELECT b.winlostdate, b.custid ,b.OpeningBalance
INTO rptDepWinlost_Main_20240425
FROM #DiffData a
    INNER JOIN dbo.rptDepWinlost_Main b WITH (NOLOCK) ON a.CustId = b.custid 


-- UPDATE: correct balance table depWL
DECLARE @Custid INT, @Winlostdate SMALLDATETIME, @DiffAmt MONEY

WHILE (1 = 1)
BEGIN
	
	SELECT TOP 1 @Custid = CustId, @Winlostdate = DateAffect, @DiffAmt = DiffAmt  FROM #DiffData WHERE Isfinished = 0

	IF @@ROWCOUNT = 0
		BREAK
	
	--  rptDepWinlost_BK
	UPDATE a 
	SET a.ClosingBalance = a.ClosingBalance + @DiffAmt,
		a.OpeningBalance = CASE WHEN a.winlostdate = @Winlostdate THEN a.OpeningBalance ELSE a.OpeningBalance + @DiffAmt END,
		a.Deposit = CASE WHEN a.winlostdate = @Winlostdate THEN a.Deposit + @DiffAmt ELSE a.Deposit END
	FROM rptDepWinlost_bk_20240425 a   
	WHERE a.custid = @Custid AND a.winlostdate >= @Winlostdate

	--  rptDepWinlost_Main
	UPDATE a 
	SET a.OpeningBalance = a.OpeningBalance + @DiffAmt
	FROM rptDepWinlost_Main_20240425 a
	WHERE a.CustID = @Custid 

	UPDATE #DiffData SET Isfinished = 1 WHERE CustId = @Custid
	
END 

GO
